# langs/hodor.py
"""Hodor — эзотерический язык, где все команды — слово «Hodor»."""

from core.base import Language
from langs.brainfuck import run_brainfuck_io as run_brainfuck
from core.translate import TRANSPILERS


HODOR_TO_BF = {
    "Hodor": ">",
    "hodor": "<",
    "HODOR": "+",
    "HODOR!": "-",
    "Hodor!": ".",
    "Hodor?": ",",
    "HODOR?": "[",
    "Hodor.": "]",
}
BF_TO_HODOR = {v: k + " " for k, v in HODOR_TO_BF.items()}


def _hodor_to_bf(src):
    keys = sorted(HODOR_TO_BF.keys(), key=len, reverse=True)
    bf = []
    i = 0
    while i < len(src):
        for k in keys:
            if src.startswith(k, i):
                bf.append(HODOR_TO_BF[k])
                i += len(k)
                break
        else:
            i += 1
    return "".join(bf)


def _hodor_print(text):
    """Hodor-программа. Для каждого символа: [-] набрать вывести."""
    parts = []
    for ch in text:
        n = ord(ch) & 0xFF
        # [-] = HODOR? HODOR! Hodor.  (открыть, минус, закрыть)
        parts.append("HODOR? HODOR! Hodor. ")
        parts.append("HODOR " * n)      # + × n
        parts.append("Hodor! ")         # .
    return "".join(parts)


def _hodor_to_python(src):
    from langs.brainfuck import _bf_to_python
    return _bf_to_python(_hodor_to_bf(src))


